      if (Notification.permission === "denied") return parentPrefLabel(labels, "notificationsPermissionDenied", "Notification permission is blocked in this browser.");
      if (parentNotificationsEnabledLocal() && Notification.permission === "granted") return parentPrefLabel(labels, "notificationsEnabledStatus", "Enabled in this browser.");
      if (Notification.permission === "granted") return parentPrefLabel(labels, "notificationsAllowedDisabledStatus", "Allowed by browser, disabled in chat settings.");
