      const muted = highContrast ? "#ffffff" : (light ? "rgba(71, 85, 105, 0.82)" : "rgba(255, 255, 255, 0.70)");
      const shadow = highContrast ? "none" : parentReadableShadowForBackground(bg);
      const scrollbarThumb = highContrast ? "#ffffff" : (light ? "rgba(100, 116, 139, 0.62)" : "rgba(255, 255, 255, 0.28)");
      const scrollbarHover = highContrast ? "#ffffff" : (light ? "rgba(71, 85, 105, 0.78)" : "rgba(130, 190, 255, 0.72)");
